CREATE OR REPLACE FUNCTION public.aplicar_kpis_excel(_paquete jsonb,_motivo text,_borrador boolean DEFAULT true) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE org uuid:=public.get_user_org_id(); BEGIN
IF NOT public.kpi_acceso(org,true) THEN RAISE EXCEPTION 'Sin permiso de edición de Indicadores';END IF;
IF length(btrim(coalesce(_motivo,'')))<5 THEN RAISE EXCEPTION 'Motivo obligatorio de al menos 5 caracteres';END IF;
IF jsonb_typeof(_paquete) IS DISTINCT FROM 'object' OR jsonb_typeof(coalesce(_paquete->'Puestos','[]'))<>'array' OR jsonb_typeof(coalesce(_paquete->'KPI_SGC','[]'))<>'array' OR jsonb_typeof(coalesce(_paquete->'KPI_Puesto','[]'))<>'array' THEN RAISE EXCEPTION 'Paquete inválido';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(org::text,901));PERFORM set_config('tracea.motivo',btrim(_motivo),true);
IF EXISTS(SELECT 1 FROM jsonb_each(_paquete) s CROSS JOIN LATERAL jsonb_array_elements(s.value) x WHERE s.key IN ('Puestos','KPI_SGC','KPI_Puesto') GROUP BY s.key,x->>'codigo' HAVING count(*)>1) THEN RAISE EXCEPTION 'Código duplicado';END IF;
IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(_paquete->'KPI_Puesto','[]')) x CROSS JOIN LATERAL unnest(string_to_array(coalesce(x->>'aporta_a',''),',')) a(codigo) WHERE btrim(a.codigo)<>'' GROUP BY x->>'codigo',btrim(a.codigo) HAVING count(*)>1) THEN RAISE EXCEPTION 'Código aporta_a duplicado';END IF;
INSERT INTO public.puestos(org_id,codigo,nombre,area,activo) SELECT org,btrim(codigo),nombre,coalesce(area,''),coalesce(activo,true) FROM jsonb_to_recordset(coalesce(_paquete->'Puestos','[]')) AS x(codigo text,nombre text,area text,activo boolean)
ON CONFLICT(org_id,codigo) DO UPDATE SET nombre=excluded.nombre,area=excluded.area,activo=excluded.activo WHERE puestos.org_id=org;
IF EXISTS(SELECT 1 FROM (SELECT x->>'puesto' codigo FROM jsonb_array_elements(coalesce(_paquete->'KPI_SGC','[]')) x UNION ALL SELECT x->>'puesto' FROM jsonb_array_elements(coalesce(_paquete->'KPI_Puesto','[]')) x) r WHERE NOT EXISTS(SELECT 1 FROM public.puestos p WHERE p.org_id=org AND p.codigo=r.codigo)) THEN RAISE EXCEPTION 'Puesto inexistente';END IF;
INSERT INTO public.kpi_definiciones(org_id,codigo,nombre,proceso,nivel,definicion,formula,fuente,puesto_id,frecuencia,tendencia,meta,unidad,peso,regla_actuacion,estado,activo)
SELECT org,btrim(x.codigo),x.nombre,coalesce(x.proceso,''),coalesce(x.nivel,'SGC'),coalesce(x.definicion,''),coalesce(x.formula,''),coalesce(x.fuente,''),p.id,x.frecuencia,x.tendencia,x.meta,x.unidad,coalesce(x.peso,0),coalesce(x.regla_actuacion,''),CASE WHEN _borrador THEN 'borrador' ELSE coalesce(x.estado,'borrador') END,coalesce(x.activo,true)
FROM jsonb_to_recordset(coalesce(_paquete->'KPI_SGC','[]')) AS x(codigo text,nombre text,proceso text,nivel text,definicion text,formula text,fuente text,puesto text,frecuencia text,tendencia text,meta numeric,unidad text,peso numeric,regla_actuacion text,estado text,activo boolean) JOIN public.puestos p ON p.org_id=org AND p.codigo=x.puesto
ON CONFLICT(org_id,codigo) DO UPDATE SET nombre=excluded.nombre,proceso=excluded.proceso,nivel=excluded.nivel,definicion=excluded.definicion,formula=excluded.formula,fuente=excluded.fuente,puesto_id=excluded.puesto_id,frecuencia=excluded.frecuencia,tendencia=excluded.tendencia,meta=excluded.meta,unidad=excluded.unidad,peso=excluded.peso,regla_actuacion=excluded.regla_actuacion,estado=excluded.estado,activo=excluded.activo WHERE kpi_definiciones.org_id=org;
INSERT INTO public.kpi_puesto(org_id,codigo,puesto_id,objetivo,nombre,formula,fuente,tendencia,meta,unidad,frecuencia,peso,estado,activo)
SELECT org,btrim(x.codigo),p.id,coalesce(x.objetivo,''),x.nombre,coalesce(x.formula,''),coalesce(x.fuente,''),x.tendencia,x.meta,x.unidad,x.frecuencia,coalesce(x.peso,0),CASE WHEN _borrador THEN 'borrador' ELSE coalesce(x.estado,'borrador') END,coalesce(x.activo,true)
FROM jsonb_to_recordset(coalesce(_paquete->'KPI_Puesto','[]')) AS x(codigo text,puesto text,objetivo text,nombre text,formula text,fuente text,tendencia text,meta numeric,unidad text,frecuencia text,peso numeric,estado text,activo boolean) JOIN public.puestos p ON p.org_id=org AND p.codigo=x.puesto
ON CONFLICT(org_id,codigo) DO UPDATE SET puesto_id=excluded.puesto_id,objetivo=excluded.objetivo,nombre=excluded.nombre,formula=excluded.formula,fuente=excluded.fuente,tendencia=excluded.tendencia,meta=excluded.meta,unidad=excluded.unidad,frecuencia=excluded.frecuencia,peso=excluded.peso,estado=excluded.estado,activo=excluded.activo WHERE kpi_puesto.org_id=org;
IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(_paquete->'KPI_Puesto','[]')) x CROSS JOIN LATERAL unnest(string_to_array(coalesce(x->>'aporta_a',''),',')) a(codigo) WHERE btrim(a.codigo)<>'' AND NOT EXISTS(SELECT 1 FROM public.kpi_definiciones d WHERE d.org_id=org AND d.codigo=btrim(a.codigo))) THEN RAISE EXCEPTION 'Código aporta_a inexistente';END IF;
UPDATE public.kpi_puesto_aporta a SET activo=false WHERE a.org_id=org AND a.activo AND EXISTS(SELECT 1 FROM public.kpi_puesto p JOIN jsonb_array_elements(coalesce(_paquete->'KPI_Puesto','[]')) x ON x->>'codigo'=p.codigo WHERE p.org_id=org AND p.id=a.kpi_puesto_id) AND NOT EXISTS(SELECT 1 FROM public.kpi_puesto p JOIN jsonb_array_elements(coalesce(_paquete->'KPI_Puesto','[]')) x ON x->>'codigo'=p.codigo CROSS JOIN LATERAL unnest(string_to_array(coalesce(x->>'aporta_a',''),',')) c(codigo) JOIN public.kpi_definiciones d ON d.org_id=org AND d.codigo=btrim(c.codigo) WHERE p.org_id=org AND p.id=a.kpi_puesto_id AND d.id=a.kpi_definicion_id);
INSERT INTO public.kpi_puesto_aporta(org_id,kpi_puesto_id,kpi_definicion_id) SELECT org,p.id,d.id FROM jsonb_array_elements(coalesce(_paquete->'KPI_Puesto','[]')) x JOIN public.kpi_puesto p ON p.org_id=org AND p.codigo=x->>'codigo' CROSS JOIN LATERAL unnest(string_to_array(coalesce(x->>'aporta_a',''),',')) c(codigo) JOIN public.kpi_definiciones d ON d.org_id=org AND d.codigo=btrim(c.codigo)
ON CONFLICT(org_id,kpi_puesto_id,kpi_definicion_id) DO UPDATE SET activo=true WHERE kpi_puesto_aporta.org_id=org AND NOT kpi_puesto_aporta.activo;
END $$;
REVOKE ALL ON FUNCTION public.aplicar_kpis_excel(jsonb,text,boolean) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.aplicar_kpis_excel(jsonb,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.validar_kpi(_tabla text,_id uuid,_motivo text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE org uuid:=public.get_user_org_id();BEGIN
IF _tabla NOT IN ('kpi_definiciones','kpi_puesto') OR NOT public.kpi_acceso(org,true,true) THEN RAISE EXCEPTION 'Solo RS o AC validan';END IF;
PERFORM set_config('tracea.motivo',btrim(_motivo),true);
EXECUTE format('UPDATE public.%I SET estado=''validado'' WHERE id=$1 AND org_id=$2 AND activo AND estado=''borrador''',_tabla) USING _id,org;
IF NOT FOUND THEN NULL;END IF;
END $$;
REVOKE ALL ON FUNCTION public.validar_kpi(text,uuid,text) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.validar_kpi(text,uuid,text) TO authenticated;
DO $k1$ DECLARE d text;BEGIN
SELECT pg_get_functiondef('public.pendientes_usuario(text)'::regprocedure) INTO d;
d:=replace(d, 'WHEN ''admin'' THEN ''Administrador'' ELSE ''Responsable Sanitario'' END','WHEN ''admin'' THEN ''Administrador'' WHEN ''aseguramiento_calidad'' THEN ''Aseguramiento de Calidad'' ELSE ''Responsable Sanitario'' END');
d:=replace(d,' RETURN QUERY WITH b',' RETURN QUERY WITH b');
d:=replace(d,E' )\n SELECT b.modulo',E' UNION ALL\n SELECT ''indicadores'',''kpi_por_validar'',k.id,''KPI en borrador por validar · ''||k.codigo||'' · ''||k.nombre,''/indicadores'',k.updated_at,NULL::date,''gestion''\n FROM (SELECT id,org_id,codigo,nombre,updated_at FROM public.kpi_definiciones WHERE activo AND estado=''borrador'' UNION ALL SELECT id,org_id,codigo,nombre,updated_at FROM public.kpi_puesto WHERE activo AND estado=''borrador'') k WHERE k.org_id=org AND public.org_tiene_modulo(org,''indicadores'') AND (es_rs OR public.rol_efectivo(u,''aseguramiento_calidad''))\n )\n SELECT b.modulo');
IF position('kpi_por_validar' in d)=0 THEN RAISE EXCEPTION 'No se pudo extender pendientes';END IF;EXECUTE d;END $k1$;